// Reaches `net`, which the root grants, and `unsafe`, which it does not.
import { netAddress, tcpConnect } from "nish:net";
import { wrappingMul } from "nish:unsafe";

const dial = (port: i32): boolean => {
  const addr: u8[] = [];
  return netAddress(addr, "127.0.0.1", port) >= 0 && tcpConnect(addr) >= 0;
};

export const fetchMixed = (port: i32): i32 => (dial(port) ? wrappingMul(port, 31) : 2);
